/* A QUANTITY IS SHORT, SO THE CONTROL IS SHORT.
 * `inline-flex` alone does not say that: as a flex item of `<Field>` — which is
 * where the component's own doc string tells you to put it — `align-self:
 * stretch` won, and a stepper for "1" was as wide as the form (owner,
 * 2026-08-24). A stated width is definite, so stretching has nothing left to
 * do, and the field keeps the measure its value actually needs. */
.number-input {
  display: inline-flex;
  inline-size: max-content;
  align-items: center;
  gap: var(--space-1);
  block-size: var(--control-height);
  padding-inline: var(--space-1);
  background: var(--background);
  border: 1px solid var(--input);
  border-radius: var(--control-radius);
}
.number-input[data-size="sm"] { block-size: var(--control-height-sm); }
.number-input[data-size="lg"] { block-size: var(--control-height-lg); }
.number-input[data-size="sm"] .number-input-field { font-size: var(--font-sm); }
.number-input[data-size="lg"] .number-input-field { font-size: var(--control-font-size-lg); }
.number-input:hover:not([data-disabled]) { border-color: var(--ring); }
/* The ring, not a recoloured border. Every sibling field draws 2px on focus;
 * this one drew 1px in a different colour, so the same keypress produced a
 * four-times-fainter answer depending on which field you were in. */
.number-input:focus-within {
  border-color: var(--ring);
  outline: var(--ring-width) solid var(--ring);
  outline-offset: var(--ring-offset);
}
.number-input[data-invalid]:focus-within { outline-color: var(--destructive); }
.number-input[data-invalid] { border-color: var(--destructive); }
/* --muted surface: drop the resting border; keep it on focus-within (the field's
 * only focus indicator) and on invalid. */
.number-input[data-surface="muted"]:not([data-invalid]):not(:focus-within) { border-color: transparent; }
.number-input[data-disabled] { opacity: 0.5; cursor: not-allowed; }

.number-input-field {
  inline-size: 3.5rem;
  border: none;
  background: transparent;
  color: var(--foreground);
  font-family: inherit;
  font-size: var(--control-font-size);
  text-align: center;
  font-variant-numeric: tabular-nums;
}
.number-input-field:focus { outline: none; }
/* Hide the native spin arrows; our minus/plus buttons replace them. */
.number-input-field::-webkit-inner-spin-button,
.number-input-field::-webkit-outer-spin-button { appearance: none; margin: 0; }
.number-input-field { appearance: textfield; }

import './NumberInput.css'
import { type InputHTMLAttributes } from 'react'
import { cn } from '../lib/cn'
import { IconButton } from '../IconButton'
import { Tooltip } from '../Tooltip'

type Props = Omit<InputHTMLAttributes<HTMLInputElement>, 'type' | 'value' | 'onChange' | 'min' | 'max' | 'step'> & {
  value: number
  onChange: (value: number) => void
  min?: number
  max?: number
  step?: number
  /** Accessible name (there is no visible label; wrap in <Field> for one). */
  label: string
  invalid?: boolean
  /** Which surface the field sits on. On `muted` (a page/PageHeader) the border
   *  is dropped since the white fill separates it; `base` (default, a white card
   *  or form) keeps the border. Invalid + focus stay visible on both. */
  surface?: 'base' | 'muted'
  /** sm / md (default) / lg — matches the shared control height/padding scale. */
  size?: 'sm' | 'md' | 'lg'
  decrementLabel?: string
  incrementLabel?: string
}

/* A number field with stepper buttons. The native <input type="number"> keeps
 * the spinbutton role, keyboard and validation; the -/+ buttons are the
 * click affordance. Clamps to min/max. Wrap in <Field> for a visible label. 
   *
   * Copy: the label carries the unit, so the number never has to — "Weight in kg",
   * not "Weight" with a kg inside the box.
   */
export function NumberInput({
  value, onChange, min, max, step = 1, label, invalid, disabled,
  decrementLabel = 'Decrease', incrementLabel = 'Increase', surface = 'base', size, className, ...rest
}: Props) {
  const clamp = (n: number) => {
    if (min !== undefined && n < min) return min
    if (max !== undefined && n > max) return max
    return n
  }
  const atMin = min !== undefined && value <= min
  const atMax = max !== undefined && value >= max
  /* Steppers scale with the field: sm/md field uses sm buttons, lg uses md. */
  const stepperSize = size === 'lg' ? 'md' : 'sm'

  return (
    <div className={cn('number-input', className)} data-invalid={invalid || undefined} data-disabled={disabled || undefined} data-surface={surface} data-size={size}>
      <Tooltip content={decrementLabel}>
        <IconButton
          icon="remove"
          size={stepperSize}
          variant="quiet"
          aria-label={decrementLabel}
          disabled={disabled || atMin}
          onClick={() => onChange(clamp(value - step))}
        />
      </Tooltip>
      <input
        type="number"
        className="number-input-field"
        value={value}
        min={min}
        max={max}
        step={step}
        disabled={disabled}
        aria-label={label}
        aria-invalid={invalid || undefined}
        onChange={(e) => { const n = Number(e.target.value); if (!Number.isNaN(n)) onChange(clamp(n)) }}
        {...rest}
      />
      <Tooltip content={incrementLabel}>
        <IconButton
          icon="add"
          size={stepperSize}
          variant="quiet"
          aria-label={incrementLabel}
          disabled={disabled || atMax}
          onClick={() => onChange(clamp(value + step))}
        />
      </Tooltip>
    </div>
  )
}
